/** Пара «корейский пример, перевод». */
export type ExPair = [string, string]
/**
 * Блок с одним текстом: абзац, заголовок, правило, формула, предупреждение, совет, «верно», произношение.
 * `deep` не показывает текст сам: это метка «дальше всё свёрнуто под заголовком» (его текст), блоки после метки лежат в раскрывающемся «Глубже» (`blocksHtml` в render.ts). Метка одна на карточку.
 */
export type TextBlock = ['p' | 'h' | 'rule' | 'formula' | 'warn' | 'tip' | 'ok' | 'pron' | 'deep', string]
/** Блок карточки: текст, список примеров или таблица (заголовки и строки). Рисует `blk()` в render.ts. */
export type Block = TextBlock | ['ex', ExPair[]] | ['tbl', string[], string[][]]

/** Первый блок нужного вида: `firstBlock(g.b, 'ex')` даёт список примеров, `firstBlock(g.b, 'formula')` текст формулы. */
export function firstBlock(b: Block[], kind: 'ex'): ExPair[] | undefined
export function firstBlock(b: Block[], kind: TextBlock[0]): string | undefined
export function firstBlock(b: Block[], kind: Block[0]) {
  return b.find(x => x[0] === kind)?.[1]
}

export interface Gram {
  id: string
  ko: string
  ru: string
  s: string
  /** подпись урока: «Урок 5» (часть 1) или «Часть 2 · Урок 5» */
  l?: string
  st: string
  d: string
  /** часть курса: 1 — «Первый шаг» (уроки 1–30), 2 — «Второй шаг»; не указана — часть 1 */
  part?: 1 | 2
  /** файл видеоурока (пока нет — в окне заглушка) */
  video?: string
  /** место в книге «서울대 한국어+ 문법 설명» (по ней идёт Лера): «единица-урок №», например «6-2 ③» — это книга 1A; для книги 1B перед местом ставится «1B », например «1B 2-1 ①»; по нему «Мои карточки» идут в порядке книги */
  bk?: string
  /** тема впереди: карточка-заглушка «ещё рано» без объяснения (`st` всегда `soon`); пройдена тема: убери поле и допиши карточку */
  ahead?: boolean
  b: Block[]
}

