/** Сколько правил грамматики на сайте: карточки-заглушки «впереди» (`ahead`) не в счёт, объяснения у них ещё нет. */
/** Сколько правил показываем в числах сайта: уроки видеокурса и свои пройденные карточки; непройденное (заглушки «впереди» и свои карточки без `ok`) не считается: пройдено только то, что отметил владелец (`st: 'ok'`). */
export const RULES_COUNT = G.filter(g => g.l || g.st === 'ok').length
/** Карточка видна сайту: урок видеокурса (открыт всем) или своя пройденная. Свои непройденные (заглушки и `soon`) только в списке «что впереди» у владельца. */
export const shownCard = (g: { l?: string; st: string }) => !!g.l || g.st === 'ok'

/** Вкладка страницы грамматики: 0 — свои карточки (без номера урока), 1 и 2 — карточки уроков видеокурса (части 1 и 2). */
export const tabOf = (g: { l?: string; part?: 1 | 2 }): 0 | 1 | 2 => (g.l ? (g.part ?? 1) : 0)

export const SECS = ['Быть и отрицание','Частицы','Место и направление','Глаголы и просьбы','Указатели и вопросы','Вежливость','Произношение','Числительные','Время','Желание и предложение','Связки'];
